      buffer.putUint8(130);
      writeValue(buffer, value.index);
    } else if (value is KeySoundKind) {
      buffer.putUint8(131);
      writeValue(buffer, value.index);
    } else if (value is ContextMenuAction) {
      buffer.putUint8(132);
      writeValue(buffer, value.index);
    } else if (value is PackKind) {
      buffer.putUint8(133);
      writeValue(buffer, value.index);
    } else if (value is PackOfferStatusMessage) {
      buffer.putUint8(134);
      writeValue(buffer, value.index);
    } else if (value is VoiceStartStatus) {
      buffer.putUint8(135);
      writeValue(buffer, value.index);
    } else if (value is VoiceEventKind) {
      buffer.putUint8(136);
      writeValue(buffer, value.index);
    } else if (value is ImageStartStatus) {
      buffer.putUint8(137);
      writeValue(buffer, value.index);
    } else if (value is ImageEventKind) {
      buffer.putUint8(138);
      writeValue(buffer, value.index);
    } else if (value is EditorInfoMessage) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    } else if (value is SelectionMessage) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    } else if (value is SurroundingTextMessage) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    } else if (value is ClipMessage) {
      buffer.putUint8(142);
      writeValue(buffer, value.encode());
    } else if (value is WindowMetricsMessage) {
      buffer.putUint8(143);
      writeValue(buffer, value.encode());
    } else if (value is SystemColorsMessage) {
      buffer.putUint8(144);
      writeValue(buffer, value.encode());
    } else if (value is RectMessage) {
      buffer.putUint8(145);
      writeValue(buffer, value.encode());
    } else if (value is WindowLayoutMessage) {
      buffer.putUint8(146);
      writeValue(buffer, value.encode());
    } else if (value is FeedbackConfigMessage) {
      buffer.putUint8(147);
      writeValue(buffer, value.encode());
    } else if (value is SecureBlobInfo) {
      buffer.putUint8(148);
      writeValue(buffer, value.encode());
    } else if (value is AppInfoMessage) {
      buffer.putUint8(149);
