    } else if (value is PackCheckMessage) {
      buffer.putUint8(151);
      writeValue(buffer, value.encode());
    } else if (value is PackStorageMessage) {
      buffer.putUint8(152);
      writeValue(buffer, value.encode());
    } else if (value is PackOfferMessage) {
      buffer.putUint8(153);
      writeValue(buffer, value.encode());
    } else if (value is VoiceRequestMessage) {
      buffer.putUint8(154);
      writeValue(buffer, value.encode());
    } else if (value is VoiceEventMessage) {
      buffer.putUint8(155);
      writeValue(buffer, value.encode());
    } else if (value is ImageRequestMessage) {
      buffer.putUint8(156);
      writeValue(buffer, value.encode());
    } else if (value is ImageEventMessage) {
